class Demo {
    static void f(long x) {
        System.out.println("long");
    }

    static void f(Integer x) {
        System.out.println("Integer");
    }
}

public class Main {
    public static void main(String[] args) {
        Demo.f(5);
    }
}

class A {
    String tag = "A";

    void who() {
        System.out.println("A.who");
    }
}

class B extends A {
    String tag = "B";

    void who() {
        System.out.println("B.who");
    }
}

public class Main {
    public static void main(String[] args) {
        A a = new B();
        System.out.println(a.tag);
        a.who();
    }
}

