class A {
    void hi() {
        System.out.println("A hi");
    }
}

class B extends A {
    void hi() {
        super.hi();
        System.out.println("B hi");
    }
}

public class Main {
    public static void main(String[] args) {
        new B().hi();
    }
}

class Base {
    Base make() {
        return new Base();
    }

    String id() {
        return "base object";
    }
}

class Sub extends Base {
    Sub make() {
        return new Sub();
    }

    String id() {
        return "sub object";
    }
}

public class Main {
    public static void main(String[] args) {
        Sub s = new Sub().make();
        System.out.println(s.id());
    }
}

